// ============================================
// GymMaster — Push notifications in the service worker
// ============================================
//
// Included in the service worker generated by vite-plugin-pwa (vite.config.js,
// workbox.importScripts). Shows the notifications the server sends
// (backend/src/services/push.service.js) even when the app is closed or the
// screen is locked. With the app open in front of the user it shows nothing:
// the notification bell, the chat and the timer take care of that.

self.addEventListener('push', (evento) => {
  let dati = {};
  try { dati = evento.data ? evento.data.json() : {}; } catch { /* plain text: the default title is used */ }

  evento.waitUntil((async () => {
    // "sempre" (always): the test notification, which is sent from the open app itself
    const finestre = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
    if (!dati.sempre && finestre.some(finestra => finestra.visibilityState === 'visible')) return;

    await self.registration.showNotification(dati.titolo || 'GymMaster', {
      body: dati.messaggio || '',
      icon: '/icons/icon-192.png',
      badge: '/icons/icon-192.png',
      // Same tag: the new one replaces the old one (a rest timer, a conversation)
      tag: dati.tag || undefined,
      renotify: Boolean(dati.tag),
      vibrate: [200, 100, 200],
      data: { percorso: dati.percorso || '/' }
    });
  })());
});

// Tap on the notification: opens the app on the right page, reusing the window if there is one
self.addEventListener('notificationclick', (evento) => {
  evento.notification.close();
  const indirizzo = new URL(evento.notification.data?.percorso || '/', self.location.origin).href;

  evento.waitUntil((async () => {
    const finestre = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
    const finestra = finestre.find(f => new URL(f.url).origin === self.location.origin);
    if (finestra) {
      await finestra.focus();
      if ('navigate' in finestra) await finestra.navigate(indirizzo).catch(() => {});
      return;
    }
    await self.clients.openWindow(indirizzo);
  })());
});
